      const q2=prog(u,.22,.4);TP[0]=lerp(120,-240,q2);TP[1]=lerp(-60,40,q2);at(tfh,{transform:`translate(${f2(TP[0])} ${f2(TP[1])})`,opacity:f2(Math.min(1,u*8))});cyt.forEach((c,i)=>{const p=prog(u,.3,.45);at(c,{cx:f2(lerp(400,bx+60,p)+i*6),cy:f2(lerp(360,by-40+i*8,p)),opacity:f2(p>0&&p<1?1:0)})});
