    const st=steps(g,90,130,[[0,U('1. Dendrit hujayra peptidni MHC I va MHC II da taqdim etadi','1. Dendritic cell presents peptide on MHC I and MHC II')],[.25,U('2. Signal 1: TCR–MHC; signal 2: CD28–B7; signal 3: IL-2','2. Signal 1: TCR–MHC; signal 2: CD28–B7; signal 3: IL-2')],[.5,U('3. CD8⁺ T zararlangan hujayradagi MHC I ni taniydi','3. CD8⁺ T recognises MHC I on the infected cell')],[.7,U('4. Perforin + granzim → apoptoz (kaspazalar)','4. Perforin + granzyme → apoptosis (caspases)')]],{size:22});
